function validate(input) {
  const [fn, args] = input;
  if (!fn || typeof fn !== 'object' || Array.isArray(fn)) return 'fn must be an object such as { "t": 0, "compute": "sum" }.';
  const keys = Object.keys(fn).sort().join(',');
  if (keys !== 'compute,t' && keys !== 'compute,error,t') return 'fn has t, compute and optionally error, nothing else.';
  if (!Number.isInteger(fn.t) || fn.t < 0 || fn.t > 1000) return 'fn.t must be an integer from 0 to 1000.';
  if (!['product', 'sum', 'max'].includes(fn.compute)) return 'fn.compute must be "product", "sum" or "max".';
  if ('error' in fn && (typeof fn.error !== 'string' || fn.error.length < 1 || fn.error.length > 30)) return 'fn.error must be a string of 1 to 30 characters.';
  if (!Array.isArray(args) || args.length < 1 || args.length > 100) return 'args needs 1 to 100 numbers.';
  if (!args.every((x) => Number.isInteger(x) && x >= 0 && x <= 10000)) return 'Each value of args is an integer from 0 to 10^4.';
  if (fn.compute === 'product') {
    let product = 1;
    for (const x of args) {
      product *= x;
      if (product > Number.MAX_SAFE_INTEGER) return 'With "product", keep the product of args at most 2^53 - 1.';
    }
  }
  return null;
}

