function adapt(input, solve, kit) {
  const [spec, args] = input;
  const fn = (callback, ...values) => {
    kit.trace(`fn(callback, ${values.join(', ')}) starts`);
    const data = spec.compute === 'sum' ? values.reduce((total, x) => total + x, 0)
      : spec.compute === 'max' ? Math.max(...values)
      : values.reduce((total, x) => total * x, 1);
    const report = () => {
      if (typeof callback !== 'function') throw new Error('fn must receive a callback function as its first argument.');
      if (spec.error === undefined) {
        kit.trace(`fn calls callback(${data})`);
        callback(data);
      } else {
        kit.trace(`fn calls callback(${data}, ${JSON.stringify(spec.error)})`);
        callback(data, spec.error);
      }
    };
    if (spec.t > 0) setTimeout(report, spec.t);
    else report();
  };
  const promised = solve(fn);
  if (typeof promised !== 'function') throw new Error('promisify must return a function.');
  kit.trace(`promised(${args.join(', ')}) is called`);
  const promise = promised(...args);
  if (!promise || typeof promise.then !== 'function') throw new Error('The promise-based function must return a promise.');
  return promise.then((value) => {
    kit.trace(`The promise resolves with ${JSON.stringify(value)}`);
    return { resolved: value };
  }, (reason) => {
    const rejected = reason instanceof Error ? String(reason) : reason;
    kit.trace(`The promise rejects with ${JSON.stringify(rejected)}`);
    return { rejected };
  });
}

