function generate(rand, size) {
  const small = size === 'small';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const compute = pick(['product', 'sum', 'max']);
  const t = small ? (rand() < 0.5 ? 0 : 1 + Math.floor(rand() * 100)) : Math.floor(rand() * 1001);
  const length = small ? 1 + Math.floor(rand() * 5) : 100;
  let args;
  if (compute === 'product') {
    args = Array.from({ length }, () => (rand() < (small ? 0.3 : 0.85) ? 1 : Math.floor(rand() * (small ? 11 : 21))));
    let product = args.reduce((total, x) => total * x, 1);
    for (let i = length - 1; i >= 0 && product > Number.MAX_SAFE_INTEGER; i--) {
      args[i] = 1;
      product = args.reduce((total, x) => total * x, 1);
    }
  } else {
    const top = small ? 10 : 10000;
    args = Array.from({ length }, () => Math.floor(rand() * (top + 1)));
  }
  const spec = { t, compute };
  if (rand() < 0.4) spec.error = pick(['Promise Rejected', 'Error', 'timeout', 'bad input', '0', 'x']);
  return [spec, args];
}
